const docs = $input.all().map(item => item.json);
const results = [];
const now = new Date().getTime();
const thirtyDaysMs = 30 * 24 * 60 * 60 * 1000;

for (const doc of docs) {
  let needsIncident = false;
  let issues = [];
  let severity = 'low';

  if (doc.integrityStatus === 'tampered' || doc.integrityStatus === 'missing') {
    needsIncident = true;
    severity = 'critical';
    issues.push(`Xâm phạm toàn vẹn tệp: ${doc.integrityStatus}`);
  }

  if (doc.healthScore < 50) {
    needsIncident = true;
    severity = 'critical';
    issues.push(`Điểm sức khỏe nguy hiểm: ${doc.healthScore}/100`);
  } else if (doc.healthScore < 80) {
    issues.push(`Điểm sức khỏe cảnh báo: ${doc.healthScore}/100`);
  }

  if (doc.expiresAt) {
    const exp = new Date(doc.expiresAt).getTime();
    if (exp < now) {
      needsIncident = true;
      severity = severity === 'critical' ? 'critical' : 'high';
      issues.push('Tài liệu đã quá hạn hiệu lực');
    } else if (exp - now <= thirtyDaysMs) {
      issues.push('Tài liệu sắp hết hạn trong 30 ngày');
    }
  }

  results.push({
    json: {
      documentId: doc._id,
      title: doc.title,
      healthScore: doc.healthScore,
      healthStatus: doc.healthStatus,
      integrityStatus: doc.integrityStatus,
      needsIncident,
      severity,
      issues,
      issuesSummary: issues.join('; ')
    }
  });
}

return results;

